	private void renderHighlightLine(Graphics2D graphics, LocalPoint itemPoint, Color color)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}

		Polygon playerTile = Perspective.getCanvasTilePoly(client, player.getLocalLocation());
		Polygon itemTile = Perspective.getCanvasTilePoly(client, itemPoint);
		Point playerCanvasPoint = Perspective.localToCanvas(client, player.getLocalLocation(), client.getPlane(), 0);
		Point itemCanvasPoint = Perspective.localToCanvas(client, itemPoint, client.getPlane(), 0);
		if (playerCanvasPoint == null || itemCanvasPoint == null)
		{
			return;
		}

		java.awt.Point playerCenter = new java.awt.Point(playerCanvasPoint.getX(), playerCanvasPoint.getY());
		java.awt.Point itemCenter = new java.awt.Point(itemCanvasPoint.getX(), itemCanvasPoint.getY());
		java.awt.Point lineStart = moveToward(playerCenter, getTileEdgePoint(playerTile, playerCenter, itemCenter), LINE_EDGE_GAP);
		java.awt.Point lineEnd = moveToward(itemCenter, getTileEdgePoint(itemTile, itemCenter, playerCenter), LINE_EDGE_GAP);

		graphics.setColor(color);
		graphics.setStroke(new BasicStroke(2));
		graphics.drawLine(lineStart.x, lineStart.y, lineEnd.x, lineEnd.y);
	}

	private java.awt.Point getTileEdgePoint(Polygon tile, java.awt.Point fromCenter, java.awt.Point toward)
	{
		if (tile == null || tile.npoints < 3)
		{
			return fromCenter;
		}

		java.awt.Point bestPoint = null;
		double bestT = Double.MAX_VALUE;

		for (int i = 0; i < tile.npoints; i++)
		{
			int next = (i + 1) % tile.npoints;
			LineIntersection intersection = getLineIntersection(
				fromCenter.x,
				fromCenter.y,
				toward.x,
				toward.y,
				tile.xpoints[i],
				tile.ypoints[i],
				tile.xpoints[next],
				tile.ypoints[next]
			);

			if (intersection != null && intersection.t > 0 && intersection.t < bestT)
			{
				bestT = intersection.t;
				bestPoint = intersection.point;
			}
		}

		return bestPoint == null ? fromCenter : bestPoint;
	}

	private LineIntersection getLineIntersection(
		double x1,
		double y1,
		double x2,
		double y2,
		double x3,
		double y3,
		double x4,
		double y4)
	{
		double denominator = ((x1 - x2) * (y3 - y4)) - ((y1 - y2) * (x3 - x4));
		if (Math.abs(denominator) < 0.0001)
		{
			return null;
		}

		double t = (((x1 - x3) * (y3 - y4)) - ((y1 - y3) * (x3 - x4))) / denominator;
		double u = (((x1 - x3) * (y1 - y2)) - ((y1 - y3) * (x1 - x2))) / denominator;
		if (u < 0 || u > 1)
		{
			return null;
		}

		java.awt.Point point = new java.awt.Point(
			(int) Math.round(x1 + (t * (x2 - x1))),
			(int) Math.round(y1 + (t * (y2 - y1)))
		);
		return new LineIntersection(point, t);
	}

	private java.awt.Point moveToward(java.awt.Point from, java.awt.Point to, double pixels)
	{
		double dx = to.x - from.x;
		double dy = to.y - from.y;
		double distance = Math.hypot(dx, dy);
		if (distance <= pixels || distance == 0)
		{
			return to;
		}

		return new java.awt.Point(
			(int) Math.round(to.x + ((dx / distance) * pixels)),
			(int) Math.round(to.y + ((dy / distance) * pixels))
		);
	}

	private static final class LootGroup
	{
		private AreaLootItem representative;
		private int totalQuantity;
		private long totalGeValue;
		private long totalHaValue;

		private LootGroup(AreaLootItem item)
		{
			representative = item;
			totalQuantity = item.getQuantity();
			totalGeValue = item.getGeValue();
			totalHaValue = item.getHaValue();
		}

		private void add(AreaLootItem item)
		{
			totalQuantity += item.getQuantity();
			totalGeValue += item.getGeValue();
			totalHaValue += item.getHaValue();
			if (item.getDistance() < representative.getDistance())
			{
				representative = item;
			}
		}

		private AreaLootItem toItem()
		{
			return new AreaLootItem(
				representative.getId(),
				representative.getStackId(),
				totalQuantity,
				representative.getName(),
				representative.getLocation(),
				representative.getDistance(),
				totalGeValue,
				totalHaValue
			);
		}
	}

	private static class LineIntersection
	{
		private final java.awt.Point point;
		private final double t;

		private LineIntersection(java.awt.Point point, double t)
		{
			this.point = point;
			this.t = t;
		}
	}
}

package com.arealoot;

import java.awt.Color;
import java.awt.Dimension;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.SwingConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;

class AreaLootPanel extends PluginPanel
{
	private static final Dimension ROW_SIZE = new Dimension(PluginPanel.PANEL_WIDTH, 38);

	private final AreaLootPlugin plugin;
	private final AreaLootConfig config;
	private final ItemManager itemManager;
	private final JLabel header = new JLabel("Nearby loot");
	private final JLabel summary = new JLabel();

	AreaLootPanel(AreaLootPlugin plugin, AreaLootConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;

		header.setForeground(ColorScheme.TEXT_COLOR);
		header.setHorizontalAlignment(SwingConstants.CENTER);
		summary.setForeground(ColorScheme.TEXT_COLOR);
		summary.setHorizontalAlignment(SwingConstants.CENTER);
		add(header);
	}

	void rebuild(List<AreaLootItem> items)
	{
		removeAll();
		int itemCount = Math.min(items.size(), Math.max(1, config.sidePanelMaxItems()));
		header.setText(items.isEmpty() ? "No nearby loot" : "Nearby loot (" + items.size() + ")");
		add(header);

		for (int i = 0; i < itemCount; i++)
		{
			add(createRow(items.get(i)));
		}

		if (items.size() > itemCount && !config.showLootCount())
		{
			JLabel more = new JLabel("+" + (items.size() - itemCount) + " more");
			more.setForeground(ColorScheme.TEXT_COLOR);
			more.setHorizontalAlignment(SwingConstants.CENTER);
			add(more);
		}
		String summaryText = getSummaryText(items);
		if (!summaryText.isEmpty())
		{
			summary.setText(summaryText);
			add(summary);
		}

		revalidate();
		repaint();
	}

	private JButton createRow(AreaLootItem item)
	{
		String quantity = item.getQuantity() > 1 ? " x" + item.getQuantity() : "";
		String geValueText = config.showGeValue()
			? "&nbsp;&nbsp;<font color='" + toHtmlColor(plugin.getGeValueTextColor(item)) + "'>" + formatGeValue(item) + "</font>"
			: "";
		String formattedDistance = formatDistance(item);
		String distanceText = formattedDistance.isEmpty()
			? ""
			: "<br><font color='" + toHtmlColor(plugin.getThemeColor("tileDistanceTextColor")) + "'>" + formattedDistance + "</font>";
		JButton row = new JButton("<html><b>" + escapeHtml(item.getName()) + "</b>" + quantity + geValueText + distanceText + "</html>");
		row.setHorizontalAlignment(SwingConstants.LEFT);
		row.setPreferredSize(ROW_SIZE);
		row.setMinimumSize(ROW_SIZE);
		row.setMaximumSize(ROW_SIZE);
		row.setFocusable(false);
		row.setForeground(ColorScheme.TEXT_COLOR);
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setIconTextGap(6);
		boolean selected = plugin.isSelectedLoot(item);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(selected ? plugin.getThemeColor("highlightOutlineColor") : ColorScheme.BORDER_COLOR, selected ? 2 : 1),
			BorderFactory.createEmptyBorder(3, 6, 3, 6)
		));
		if (config.listIconSize() != AreaLootConfig.ListIconSize.NONE)
		{
			AsyncBufferedImage image = itemManager.getImage(item.getId(), item.getQuantity(), false);
			if (image != null)
			{
				image.addTo(row);
			}
		}
		row.addActionListener(e ->
		{
			if (plugin.isSelectedLoot(item))
			{
				plugin.clearSelectedLoot();
			}
			else
			{
				plugin.selectLoot(item);
			}
		});
		return row;
	}

	private String formatGeValue(AreaLootItem item)
	{
		return AreaLootValueFormatter.formatGeValue(item.getGeValue());
	}

	private String formatGeValue(long value)
	{
		return AreaLootValueFormatter.formatGeValue(value);
	}

	private String formatLongGeValue(long value)
	{
		return AreaLootValueFormatter.formatLongGeValue(value);
	}

	private String getSummaryText(List<AreaLootItem> items)
	{
		if (items.isEmpty() || (!config.showLootCount() && config.totalGeValueMode() == AreaLootConfig.TotalGeValueMode.NONE))
		{
			return "";
		}

		String lootCountText = config.showLootCount()
			? "<font color='" + toHtmlColor(plugin.getThemeColor("lootCountTextColor")) + "'>" + items.size() + (items.size() == 1 ? " item" : " items") + "</font>"
			: "";
		String totalGeValueText = getTotalGeValueText(items);
		if (lootCountText.isEmpty() && totalGeValueText.isEmpty())
		{
			return "";
		}
		if (!lootCountText.isEmpty() && !totalGeValueText.isEmpty())
		{
			return "<html>" + lootCountText + "&nbsp;|&nbsp;" + totalGeValueText + "</html>";
		}
		return "<html>" + lootCountText + totalGeValueText + "</html>";
	}

	private String getTotalGeValueText(List<AreaLootItem> items)
	{
		if (items.size() <= 1)
		{
			return "";
		}

		switch (config.totalGeValueMode())
		{
			case LONG:
				return "<font color='" + toHtmlColor(plugin.getThemeColor("totalGeValueTextColor")) + "'>Total: " + formatLongGeValue(getTotalGeValue(items)) + "</font>";
			case SHORT:
				return "<font color='" + toHtmlColor(plugin.getThemeColor("totalGeValueTextColor")) + "'>" + formatGeValue(getTotalGeValue(items)) + "</font>";
			case NONE:
			default:
				return "";
		}
	}

	private long getTotalGeValue(List<AreaLootItem> items)
	{
		long total = 0;
		for (AreaLootItem item : items)
		{
			total += item.getGeValue();
		}
		return total;
	}

	private String formatDistance(AreaLootItem item)
	{
		switch (config.tileDistanceMode())
		{
			case LONG:
				return item.getDistance() + (item.getDistance() <= 1 ? " Tile" : " Tiles");
			case SHORT:
				return item.getDistance() + "t";
			case NONE:
			default:
				return "";
		}
	}

	private String toHtmlColor(Color color)
	{
		return String.format("#%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
	}

	private String escapeHtml(String text)
	{
		return text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;")
			.replace("\"", "&quot;");
	}
}

