	boolean shouldShowOverlayList()
	{
		if (shouldShowOverlayStatus())
		{
			return true;
		}

		return manualOverlayEnabled || forceOverlayActive || (autoOverlayEnabled && !nearbyLoot.isEmpty() && isAutoShowWindowOpen()) || overlayFadeOutActive;
	}

	private boolean isAutoShowWindowOpen()
	{
		if (config.autoShowMode() == AreaLootConfig.AutoShowMode.ON_KILL)
		{
			if (lastKillTick < 0)
			{
				return false;
			}

			int now = client.getTickCount();
			int timeoutTicks = config.onKillTimeoutTicks();
			return timeoutTicks <= 0 || now - lastKillTick < timeoutTicks;
		}

		return true;
	}

	boolean isOverlayAutoModeActive()
	{
		return autoOverlayEnabled;
	}

	boolean shouldShowOverlayStatus()
	{
		return System.currentTimeMillis() < overlayStatusUntilMillis;
	}

	float getOverlayStatusAlpha()
	{
		long remainingMillis = overlayStatusUntilMillis - System.currentTimeMillis();
		if (remainingMillis <= 0)
		{
			return 0.0f;
		}

		return Math.min(1.0f, remainingMillis / (float) OVERLAY_STATUS_FADE_MILLIS);
	}

