	private void updateThemePanelNavigation()
	{
		if (!config.themeSharingPanelEnabled())
		{
			if (themeNavButton != null)
			{
				clientToolbar.removeNavigation(themeNavButton);
				themeNavButton = null;
				themePanel = null;
			}
			return;
		}

		if (themeNavButton != null)
