			return;
		}

		themePanel = new AreaLootThemePanel(this);
		themeNavButton = NavigationButton.builder()
			.tooltip("Area Loot Themes")
			.icon(createThemeIcon())
			.panel(themePanel)
			.priority(6)
			.build();
