	private void addThemeButton(JPanel panel, String text, String tooltip, int x, int y, Runnable action)
	{
		JButton button = new JButton(text);
		button.setToolTipText(tooltip);
		button.addActionListener(e -> action.run());

		GridBagConstraints constraints = new GridBagConstraints();
		constraints.gridx = x;
		constraints.gridy = y;
		constraints.weightx = 1;
		constraints.fill = GridBagConstraints.HORIZONTAL;
		constraints.insets = new Insets(y == 0 ? 0 : 4, x == 0 ? 0 : 3, 0, x == 1 ? 0 : 3);
		panel.add(button, constraints);
	}

	private JPanel createSectionPanel()
	{
		return createSectionPanel(false);
	}

	private JPanel createSectionPanel(boolean active)
	{
		JPanel panel = new JPanel();
		panel.setBackground(active ? ACTIVE_ROW_COLOR : ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(active
			? BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(STATUS_SUCCESS),
				BorderFactory.createEmptyBorder(7, 7, 7, 7))
			: BorderFactory.createEmptyBorder(8, 8, 8, 8));
		return panel;
	}

	private JLabel sectionLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(FIELD_TEXT_COLOR);
		return label;
	}

	private void styleTextField(JTextField field)
	{
		field.setForeground(FIELD_TEXT_COLOR);
		field.setCaretColor(FIELD_TEXT_COLOR);
		field.setBackground(FIELD_BACKGROUND_COLOR);
		field.setSelectedTextColor(Color.WHITE);
		field.setSelectionColor(ColorScheme.MEDIUM_GRAY_COLOR);
	}

	private void styleTextArea(JTextArea textArea)
	{
		textArea.setForeground(FIELD_TEXT_COLOR);
		textArea.setCaretColor(FIELD_TEXT_COLOR);
		textArea.setBackground(FIELD_BACKGROUND_COLOR);
		textArea.setSelectedTextColor(Color.WHITE);
		textArea.setSelectionColor(ColorScheme.MEDIUM_GRAY_COLOR);
	}

	private void createFromCurrent()
	{
		try
		{
			plugin.createThemeFromCurrentColors(createThemeName.getText());
			createThemeName.setText("");
			setStatus("Theme saved", STATUS_SUCCESS);
			setActionCard(EMPTY_CARD);
			rebuild();
		}
		catch (RuntimeException ex)
		{
			setStatus(ex.getMessage(), STATUS_ERROR);
		}
	}

	private void createFromImport()
	{
		try
		{
			plugin.importNamedColorTheme(importThemeName.getText(), importText.getText());
			importThemeName.setText("");
			importText.setText("");
			setStatus("Theme imported", STATUS_SUCCESS);
			setActionCard(EMPTY_CARD);
			rebuild();
		}
		catch (RuntimeException ex)
		{
			setStatus(ex.getMessage(), STATUS_ERROR);
		}
	}

	private void applyTheme(String name)
	{
		try
		{
			plugin.applyNamedColorTheme(name);
			setStatus("Applied " + name, STATUS_SUCCESS);
		}
		catch (RuntimeException ex)
		{
			setStatus(ex.getMessage(), STATUS_ERROR);
		}
	}

	private void updateTheme(String name)
	{
		try
		{
			plugin.updateNamedColorThemeFromCurrent(name);
			setStatus("Updated " + name, STATUS_SUCCESS);
			rebuild();
		}
		catch (RuntimeException ex)
		{
			setStatus(ex.getMessage(), STATUS_ERROR);
		}
	}

	private void exportTheme(String name)
	{
		try
		{
			plugin.copyNamedColorThemeToClipboard(name);
			setStatus("Copied " + name, STATUS_SUCCESS);
		}
		catch (RuntimeException ex)
		{
			setStatus(ex.getMessage(), STATUS_ERROR);
		}
	}

	private void deleteTheme(String name)
	{
		if (!confirm("Delete theme?", "Delete \"" + name + "\"?"))
		{
			return;
		}

		plugin.deleteNamedColorTheme(name);
		setStatus("Deleted " + name, STATUS_SUCCESS);
		setActionCard(EMPTY_CARD);
		rebuild();
	}

	private void confirmOverwriteTheme(String name)
	{
		if (confirm("Overwrite theme?", "Replace \"" + name + "\" with the current config colors?"))
		{
			updateTheme(name);
		}
	}

	private boolean confirm(String title, String message)
	{
		return JOptionPane.showConfirmDialog(
			this,
			message,
			title,
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE) == JOptionPane.YES_OPTION;
	}

	private void setActionCard(String card)
	{
		actionPanel.removeAll();
		switch (card)
		{
			case CREATE_CARD:
				actionPanel.add(createCurrentThemeCard(), BorderLayout.CENTER);
				break;
			case IMPORT_CARD:
				actionPanel.add(createImportThemeCard(), BorderLayout.CENTER);
				break;
			case EMPTY_CARD:
			default:
				actionPanel.add(createEmptyCard(), BorderLayout.CENTER);
				break;
		}

		actionPanel.revalidate();
		actionPanel.repaint();
	}

	private void setStatus(String message, Color color)
	{
		status.setText(message == null || message.isEmpty() ? " " : message);
		status.setForeground(color);
	}
}

package com.arealoot;

import java.awt.Color;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.ColorUtil;

final class AreaLootUpdateNotice
{
	static final String NOTICE_ID = "2.3.0";
	static final String MESSAGE = "Area Loot plugin has updated. See the plugin config for new settings!";

	private static final Color NOTICE_COLOR = new Color(160, 45, 45);
	private static final String CONFIG_GROUP = "area-loot";
	private static final String LAST_NOTICE_ID_KEY = "lastUpdateNoticeId";

	private AreaLootUpdateNotice()
	{
	}

	static void announceIfNeeded(
		ConfigManager configManager,
		ChatMessageManager chatMessageManager,
		boolean disableUpdateNotifications)
	{
		String lastNoticeId = configManager.getConfiguration(CONFIG_GROUP, LAST_NOTICE_ID_KEY);
		if (NOTICE_ID.equals(lastNoticeId))
		{
			return;
		}

		if (!disableUpdateNotifications)
		{
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(ColorUtil.wrapWithColorTag(MESSAGE, NOTICE_COLOR))
				.build());
		}
		configManager.setConfiguration(CONFIG_GROUP, LAST_NOTICE_ID_KEY, NOTICE_ID);
	}
}

package com.arealoot;

final class AreaLootValueFormatter
{
	private AreaLootValueFormatter()
	{
	}

	static String formatGeValue(long value)
	{
		if (value >= 10_000_000)
		{
			return (value / 1_000_000) + "m";
		}
		if (value >= 1_000_000)
		{
			return String.format("%.1fm", value / 1_000_000.0);
		}
		if (value >= 10_000)
		{
			return (value / 1_000) + "k";
		}
		if (value >= 1_000)
		{
			return String.format("%.1fk", value / 1_000.0);
		}
		return value + "gp";
	}

	static String formatLongGeValue(long value)
	{
		String digits = Long.toString(value);
		StringBuilder formatted = new StringBuilder(digits.length() + (digits.length() - 1) / 3 + 2);
		for (int i = 0; i < digits.length(); i++)
		{
			if (i > 0 && (digits.length() - i) % 3 == 0)
			{
				formatted.append(',');
			}
			formatted.append(digits.charAt(i));
		}
		return formatted.append("gp").toString();
	}
}

package com.arealoot;

import com.google.gson.Gson;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class AreaLootColorSettingsTest
{
	@Test
	public void exportAndImportRoundTripsThemeColors()
	{
		Map<String, String> colors = new LinkedHashMap<>();
		colors.put("overlayBackgroundColor", "-11053225");
		colors.put("highlightMenuTextColor", "-16724737");
		colors.put("unknownColor", "-1");

		String json = AreaLootColorSettings.exportToJson("Test", colors, new Gson());
		Map<String, String> imported = AreaLootColorSettings.importFromJson(json);

		Assert.assertEquals(1, imported.size());
		Assert.assertEquals("-11053225", imported.get("overlayBackgroundColor"));
		Assert.assertFalse(imported.containsKey("highlightMenuTextColor"));
		Assert.assertFalse(imported.containsKey("unknownColor"));
	}

	@Test
	public void importTranslatesPlayerExamineThemeColors()
	{
		Map<String, String> imported = AreaLootColorSettings.importFromJson(
			"{\"plugin\":\"player-examine\",\"colors\":{\"overlayHeaderTextColor\":\"-1\",\"totalGeTextColor\":\"-2\",\"valueHighlightColor\":\"-3\"}}");

		Assert.assertEquals("-1", imported.get("overlayHeaderColor"));
		Assert.assertEquals("-2", imported.get("geValueTextColor"));
		Assert.assertEquals("-3", imported.get("overlaySelectedRowColor"));
		Assert.assertFalse(imported.containsKey("highlightMenuTextColor"));
	}

	@Test
	public void importAcceptsQuotedThemeJson()
	{
		Map<String, String> imported = AreaLootColorSettings.importFromJson(
			"\"{\\\"plugin\\\":\\\"area-loot\\\",\\\"colors\\\":{\\\"overlayTextColor\\\":\\\"-4\\\"}}\"");

		Assert.assertEquals("-4", imported.get("overlayTextColor"));
	}

	@Test
	public void importAcceptsStoredThemeMap()
	{
		Map<String, String> imported = AreaLootColorSettings.importFromJson(
			"{\"My theme\":\"{\\\"plugin\\\":\\\"area-loot\\\",\\\"colors\\\":{\\\"overlayBorderColor\\\":\\\"-5\\\"}}\"}");

		Assert.assertEquals("-5", imported.get("overlayBorderColor"));
	}

	@Test(expected = IllegalArgumentException.class)
	public void importRejectsUnknownPlugins()
	{
		AreaLootColorSettings.importFromJson("{\"plugin\":\"unknown\",\"colors\":{}}");
	}
}

